#!/usr/bin/env python3
"""Patch the Android scaffold generated by the installed Flutter stable SDK.

Flutter templates may use either Groovy Gradle files (.gradle) or Kotlin DSL
files (.gradle.kts). This script deliberately supports both formats.
"""
from pathlib import Path
import re
import sys

ROOT = Path(__file__).resolve().parents[1]
ANDROID = ROOT / "android"


def first_existing(*paths: Path) -> Path:
    for path in paths:
        if path.is_file():
            return path
    searched = ", ".join(str(p.relative_to(ROOT)) for p in paths)
    raise FileNotFoundError(f"None of these expected files exists: {searched}")


def version_tuple(value: str) -> tuple[int, ...]:
    numbers = [int(x) for x in re.findall(r"\d+", value)[:3]]
    return tuple(numbers + [0] * (3 - len(numbers)))


def bump_plugin_version(text: str, plugin_id: str, minimum: str) -> tuple[str, bool]:
    # Matches Groovy: id "plugin.id" version "x" and Kotlin DSL: id("plugin.id") version "x".
    pattern = re.compile(
        r'(\bid\s*\(?\s*["\']' + re.escape(plugin_id) +
        r'["\']\s*\)?\s+version\s+["\'])([^"\']+)(["\'])'
    )
    changed = False

    def replace(match: re.Match[str]) -> str:
        nonlocal changed
        current = match.group(2)
        if version_tuple(current) < version_tuple(minimum):
            changed = True
            return match.group(1) + minimum + match.group(3)
        return match.group(0)

    return pattern.sub(replace, text), changed


def patch_min_sdk(text: str) -> tuple[str, bool]:
    # Both Groovy and Kotlin DSL commonly use `minSdk = flutter.minSdkVersion`.
    updated, count1 = re.subn(
        r'(?m)(\bminSdk\s*=\s*)flutter\.minSdkVersion\b', r'\g<1>24', text
    )
    updated, count2 = re.subn(
        r'(?m)(\bminSdkVersion\s+)flutter\.minSdkVersion\b', r'\g<1>24', updated
    )
    return updated, bool(count1 or count2)


def main() -> int:
    settings_file = first_existing(
        ANDROID / "settings.gradle.kts",
        ANDROID / "settings.gradle",
    )
    app_gradle = first_existing(
        ANDROID / "app" / "build.gradle.kts",
        ANDROID / "app" / "build.gradle",
    )
    wrapper_file = ANDROID / "gradle" / "wrapper" / "gradle-wrapper.properties"
    if not wrapper_file.is_file():
        raise FileNotFoundError(
            "Flutter scaffold did not create android/gradle/wrapper/gradle-wrapper.properties"
        )

    settings_text = settings_file.read_text(encoding="utf-8")
    changes: list[str] = []
    for plugin, minimum in (
        ("com.android.application", "8.12.1"),
        ("org.jetbrains.kotlin.android", "2.2.0"),
        ("kotlin-android", "2.2.0"),
    ):
        settings_text, changed = bump_plugin_version(settings_text, plugin, minimum)
        if changed:
            changes.append(f"Raised {plugin} to at least {minimum}")
    settings_file.write_text(settings_text, encoding="utf-8")

    app_text = app_gradle.read_text(encoding="utf-8")
    app_text, min_changed = patch_min_sdk(app_text)
    if min_changed:
        changes.append("Set Android minSdk to 24 for share_plus compatibility")
    app_gradle.write_text(app_text, encoding="utf-8")

    wrapper_text = wrapper_file.read_text(encoding="utf-8")
    match = re.search(r"distributionUrl=.*?gradle-([0-9.]+)-(all|bin)\.zip", wrapper_text)
    if not match:
        raise RuntimeError("Could not parse Gradle distributionUrl in gradle-wrapper.properties")

    gradle_version = match.group(1)
    # AGP 8.12.x requires Gradle 8.13. Keep Gradle 8.x for AGP 8.x; avoid
    # accidentally pairing AGP 8.x with Gradle 9.x from an unrelated template.
    agp_match = re.search(
        r'\bid\s*\(?\s*["\']com\.android\.application["\']\s*\)?\s+version\s+["\']([^"\']+)["\']',
        settings_text,
    )
    agp_version = agp_match.group(1) if agp_match else "unknown"
    agp_major = version_tuple(agp_version)[0] if agp_version != "unknown" else 0
    current_gradle = version_tuple(gradle_version)
    desired_gradle = None
    if agp_major == 8 and (current_gradle[0] > 8 or current_gradle < version_tuple("8.13")):
        desired_gradle = "8.13"
    elif agp_major >= 9 and current_gradle < version_tuple("9.0"):
        # Only upgrade a Gradle 8 wrapper when the generated AGP is already 9.x.
        desired_gradle = "9.0"

    if desired_gradle:
        wrapper_text = re.sub(
            r"gradle-[0-9.]+-(all|bin)\.zip",
            lambda m: f"gradle-{desired_gradle}-{m.group(1)}.zip",
            wrapper_text,
        )
        changes.append(f"Aligned Gradle wrapper to {desired_gradle} for AGP {agp_version}")
    wrapper_file.write_text(wrapper_text, encoding="utf-8")

    print(f"Gradle settings: {settings_file.relative_to(ROOT)}")
    print(f"App Gradle file: {app_gradle.relative_to(ROOT)}")
    print(f"Detected AGP: {agp_version}; Gradle wrapper: {desired_gradle or gradle_version}")
    for item in changes:
        print(f"- {item}")
    print("Android scaffold patch completed.")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print(f"Android scaffold patch failed: {exc}", file=sys.stderr)
        raise
